// DENORMALIZED: All data in one table
record OrderDenormalized(
    Long orderId,
    String customerName,
    String customerEmail,     // Repeated for every order
    String customerAddress,   // Repeated for every order
    String productName,
    BigDecimal productPrice,
    Integer quantity
) {}

// NORMALIZED: Data split into related tables
record Customer(
    Long customerId,
    String name,
    String email,
    String address            // Stored once
) {}

record Product(
    Long productId,
    String name,
    BigDecimal price          // Updated in one place
) {}

record Order(
    Long orderId,
    Long customerId,          // Foreign key reference
    Long productId,           // Foreign key reference
    Integer quantity,
    LocalDateTime orderDate
) {}

// VIOLATES 1NF: Multi-valued column
record CustomerBad(
    Long customerId,
    String name,
    String phoneNumbers       // "555-1234, 555-5678, 555-9999"
) {}

// Cannot query: WHERE phoneNumbers = '555-1234' won't work
// Cannot index efficiently

// CONFORMS TO 1NF: Atomic values, separate table
@Entity
class Customer {
    @Id
    private Long customerId;  // Primary key ensures unique rows
    private String name;

    @OneToMany(mappedBy = "customer")
    private List<PhoneNumber> phoneNumbers;
}

@Entity
class PhoneNumber {
    @Id
    private Long phoneId;
    private String number;    // Single atomic value per row

    @ManyToOne
    private Customer customer;
}

// Now queryable: WHERE phone_number.number = '555-1234'

// DENORMALIZED: All data in orders table
record OrderDenormalized(
    Long orderId,
    String customerName,
    String customerEmail,
    String customerAddress,
    String productName,
    BigDecimal productPrice,
    Integer quantity
) {}

// UPDATE ANOMALY: Customer moves, must update many rows
// UPDATE orders SET customer_address = 'New Address' WHERE customer_name = 'Alice'
// If you miss some orders, Alice has multiple addresses

// INSERTION ANOMALY: Cannot add product without an order
// No way to INSERT a product until someone buys it

// DELETION ANOMALY: Delete last order loses customer
// DELETE FROM orders WHERE order_id = 999
// If this was Alice's only order, all her contact info is gone

// NORMALIZED: Separate tables prevent all three
@Entity class Customer { @Id Long id; String name, email, address; }
@Entity class Product { @Id Long id; String name; BigDecimal price; }
@Entity class Order { @Id Long id; Long customerId; Long productId; Integer qty; }

// VIOLATES 2NF: Partial dependency on product_id
@Entity
class OrderItemBad {
    @EmbeddedId
    private OrderItemId id;    // Composite key

    private String productName;      // Depends only on product_id
    private BigDecimal productPrice; // Depends only on product_id
    private Integer quantity;
}

record OrderItemId(
    Long orderId,
    Long productId
) implements Serializable {}

// CONFORMS TO 2NF: Split into separate tables
@Entity
class OrderItem {
    @EmbeddedId
    private OrderItemId id;

    @ManyToOne
    @MapsId("productId")       // Links to full product details
    private Product product;

    private Integer quantity;  // Depends on entire composite key
}

@Entity
class Product {
    @Id
    private Long productId;
    private String name;       // Stored once
    private BigDecimal price;  // Stored once
}

// VIOLATES 3NF: City depends on zip_code, not student_id
@Entity
class StudentBad {
    @Id
    private Long studentId;
    private String name;
    private String zipCode;
    private String city;        // Transitive: studentId -> zipCode -> city
    private String state;
}

// If zip code 94105 changes from "San Francisco" to "SF",
// must update all students with that zip

// CONFORMS TO 3NF: Separate location reference data
@Entity
class Student {
    @Id
    private Long studentId;
    private String name;

    @ManyToOne
    @JoinColumn(name = "zip_code")
    private ZipCode location;   // Foreign key to location details
}

@Entity
class ZipCode {
    @Id
    private String zipCode;
    private String city;        // Stored once per zip
    private String state;
}

// DENORMALIZED: Multiple 1NF, 2NF, 3NF violations
record OrderFlat(
    Long orderId,
    Long customerId,
    String customerName,
    String customerZip,
    String customerCity,        // Transitive: zip -> city
    Long productId,
    String productName,         // Partial dependency on productId
    BigDecimal productPrice,    // Partial dependency on productId
    String categories,          // "Electronics,Gadgets" (non-atomic)
    Integer quantity
) {}

// 1NF: Atomic values, separate categories
record Order1NF(Long orderId, Long customerId, String customerName,
                String zip, String city, Long productId,
                String productName, BigDecimal price, Integer quantity) {}
record OrderCategory(Long orderId, Long productId, String category) {}

// 2NF: Remove partial dependencies (product details)
record Order2NF(Long orderId, Long customerId, String customerName,
                String zip, String city, Long productId, Integer quantity) {}
record Product(Long productId, String name, BigDecimal price) {}

// 3NF: Remove transitive dependencies (zip -> city)
record Order3NF(Long orderId, Long customerId, Long productId, Integer quantity) {}
record Customer(Long customerId, String name, String zip) {}
record ZipCode(String zip, String city, String state) {}
